"""Cuaderno del estudiante, 3.º medio Lengua y Literatura FG, OAC 09 (investigación ética sobre lenguaje y literatura).

Todas las fuentes, autores, libros, años y cifras son inventados («de ejemplo») y sirven solo para practicar; ninguno existe.
Los formatos de cita son modelos de ejemplo: el docente indica cuál usar en el curso.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fg_leli_common import L, E, arith  # noqa: E402,F401

OA = "FG-LELI-3M-OAC-09"


def AB(q, right, wrong, why):
    """Pregunta de dos alternativas; la correcta se escribe primero y el registro la reubica."""
    return E(f"{q} A) {right} B) {wrong}", f"A) {right}", why)


